package input

import "strings"

// publicIDLength is the number of base62 characters after the prefix, as
// generated by the public_id() SQL function.
const publicIDLength = 14

// PublicID reports whether id is prefix_ followed by 14 base62
// characters, the shape PostgreSQL's CHECK constraints enforce. Paths with any
// other value are answered without a query.
func PublicID(prefix, id string) bool {
	rest, ok := strings.CutPrefix(id, prefix+"_")
	if !ok || len(rest) != publicIDLength {
		return false
	}
	for _, c := range rest {
		if !(c >= '0' && c <= '9' || c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z') {
			return false
		}
	}
	return true
}
